// th14_s2_b1 — TH14 v1.00b Stage 2 boss nonspell (st02bs.ecl::Boss1, lines 56-105)
// Source closure: Boss1At (107-134), Boss1_at (136-159), Boss1_at2 (161-213).
// Entry state: common Boss entry at (0,128), hurtbox 40x40 -> r20, hitbox 48x48 -> r24,
// moveLimit(0,128,280,64). No DPS: HP interrupt (1400) unreachable; the 2280-frame
// interrupt is implemented as SRC_LIMIT below.

const TIME_LIMIT: int = 2764;      // 120 opening + 2640 window + 4 startup (task.md)
const OPENING_BUFFER: int = 120;
const SRC_LIMIT: int = 2280;       // setInterrupt(0, 1400, 2280, "BossCard1") time field

// TH14 synthetic bullet vocabulary (card-local copy; see bullet-types.md).
const TH14_RICE: int = 480;        // source type 8
const TH14_BIG_BALL: int = 640;    // source type 18
const BULLET_COLOR: int = 2;       // source color 2 for both emitters

// etEx WAIT 200 -> DELETE (Boss1_at EX records 0x80000000 a=200 / 0x400 a=0).
xformdef BOSS1AT_BULLET {
    set_life(200);
}

// etEx VELTIME(60 -> speed 0, keep angle), WAIT 60, VELTIME(90 -> v, keep angle).
xformdef BOSS1AT2_BULLET(v: fx) {
    @60 step_speed(0fx, 60);
    @60 add_speed(0fx);
    @90 step_speed(v, 90);
}

// ---- training shell: control carries the phase, real boss at source entry (0,128) ----

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    set_enemy_flag(ENEMY_KILLALL_EXEMPT, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 12400, 0, 0, 0, boss_main);
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}

// ---- Boss1 main loop ----
// Shared slots: int0 = moveRand step count, int1 = source frame clock,
// int2 = current moveRand duration; fx0/fx1 = logical unit direction.

async sub boss_main() {
    set_invuln(65535);
    set_hurtbox(20fx);                 // setHurtbox(40.0f, 40.0f): r = 40 * 0.5
    set_hitbox(24fx);                  // setHitbox(48.0f, 48.0f): r = 48 * 0.5
    set_self_int(0, 0);
    set_self_int(1, 0);
    set_self_int(2, 0);
    spawn boss_at2_emitter();          // @Boss1_at2() async at entry (line 64)
    loop {
        src_wait(60);                  // Boss1_240: EffChargePoint2 is presentation-only
        if self_int(1) >= SRC_LIMIT { break; }
        src_wait(30);                  // anmSelect(3)/anmSelectedPlay(0) are presentation-only
        if self_int(1) >= SRC_LIMIT { break; }
        boss_spawn_ring();             // diffF/diffI + Boss1_532 ring creation
        src_wait(60);
        if self_int(1) >= SRC_LIMIT { break; }
        boss_begin_move();             // moveRand([-1], 4, 0.75f)
        src_move_wait();
        if self_int(1) >= SRC_LIMIT { break; }
    }
    // boundary_context (BossCard1 entry): stop this attack, keep necessary exit.
    move_vel(0, 0deg, 0fx, EASE_LINEAR);
    kill_all_enemies(KILL_SILENT);     // source enmKillAll(): run out the spawned heads
    loop { wait(1); }
}

// waits n source frames, capped at SRC_LIMIT; updates the shared clock (int1).
sub src_wait(n: int) {
    var t: int = self_int(1);
    var d: int = n;
    if t + d > SRC_LIMIT { d = SRC_LIMIT - t; }
    if d > 0 { wait(d); }
    set_self_int(1, t + d);
}

// diffF(%A, .785398, .3926991, .3926991, .3926991) -> 8192 / 4096 BAM
// diffI($B, 8, 16, 16, 16); %F0 starts at 0.392699 = 4096 BAM
sub boss_spawn_ring() {
    var rank: int = global(GVAR_RANK);
    var step: int = 4096;
    var n: int = 16;
    if rank == RANK_EASY {
        step = 8192;
        n = 8;
    }
    var spd: fx = 1.0fx;               // Boss1At second moveVel: !E/N 1.0f, !LO 1.5f
    if rank >= RANK_HARD { spd = 1.5fx; }
    var ang: int = 4096;
    for i in 0..n {
        // enmCreate("Boss1At", 0.0f, 0.0f, 10, 10, 0) relative to the parent FINAL.
        _ = spawn_enemy($self_x, $self_y, 10, 0, 0, 0, boss1at(ang as angle, spd));
        ang = ang + step;              // %F0 = %F0 + %A after each creation
    }
}

// moveRand(frames, 4, 0.75f) with moveLimit(0,128,280,64):
// inner region x +-70 (width/4), y 112..144; clamp x [-140,140], y [96,160].
sub boss_begin_move() {
    var rank: int = global(GVAR_RANK);
    var total: int = 120;              // !E/N 120, !H 80, !LO 60
    if rank == RANK_HARD { total = 80; }
    else if rank == RANK_LUNATIC { total = 60; }
    set_self_int(2, total);
    set_self_int(0, 0);
    var r: int = rand(65536) - 32768;  // signed unit * pi, unwrapped BAM
    var a: int = r / 3;
    if $self_x < -70fx {
        a = r / 3;
    } else if $self_x > 70fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    // native +-pi/2 guard, epsilon 0.05 rad (nearest BAM boundary 522)
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    set_self_fx(0, cos(a as angle));
    set_self_fx(1, sin(a as angle));
    boss_arm_step();
}

// speed(k) = 0.75 * (total-k)/total, applied per source movement tick.
sub boss_arm_step() {
    var total: int = self_int(2);
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var sp: fx = 0fx;
    if k < total { sp = 0.75fx * (total - k) / total; }
    var nx: fx = $self_x + self_fx(0) * sp;
    var ny: fx = $self_y + self_fx(1) * sp;
    if nx < -140fx { nx = -140fx; }
    if nx > 140fx { nx = 140fx; }
    if ny < 96fx { ny = 96fx; }
    if ny > 160fx { ny = 160fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

sub src_move_wait() {
    var total: int = self_int(2);
    var i: int = 0;
    while i < total {
        if self_int(1) >= SRC_LIMIT { break; }
        wait(1);
        set_self_int(1, self_int(1) + 1);
        boss_arm_step();
        i = i + 1;
    }
}

// ---- Boss1At: one spawned head ----

async sub boss1at(dir: angle, spd: fx) {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);  // flagSet(288): 0x20 closes both hit and body gates
    move_vel(0, dir, 32fx, EASE_LINEAR);
    wait(1);
    move_vel(0, dir, spd, EASE_LINEAR);
    spawn boss1_at_emitter();          // @Boss1_at() async
    // 10 x (wait 60; moveAngleTime(120, mode7, RANDRAD/450)); replaced every 60 frames,
    // so each 60-frame segment turns by 60 * delta (mode7 adds delta per update).
    for i in 0..10 {
        wait(60);
        var d: int = (rand(65536) - 32768) / 450;   // RANDRAD/450 in BAM per frame
        move_angle(60, $self_angle + ((60 * d) as angle), EASE_LINEAR);
    }
}

// ---- Boss1_at: head's slow rice stream along its own travel direction ----

async sub boss1_at_emitter() {
    sh_reset(0);
    sh_sprite(0, TH14_RICE, BULLET_COLOR);
    sh_ring(0, 1);
    sh_count(0, 1, 1);
    sh_speed(0, 0.01fx, 0fx);          // etSpeed(0.01f, 1.0f) with 1 layer -> s0
    sh_angle(0, 0deg, 0deg);
    sh_xform(0, BOSS1AT_BULLET);
    for i in 0..700 {
        sh_angle(0, $self_angle, 0deg);  // etAngle(0, %ABS_ANGLE, 0.0f)
        sh_fire(0);
        wait(4);
    }
}

// ---- Boss1_at2: boss fan, stop-and-go bullets ----

sub boss1at2_fire(a: angle, v: fx) {
    // ANIM(a=1) birth displacement: position -= 4 * velocity = 8px opposite the angle.
    _ = fire(TH14_BIG_BALL, BULLET_COLOR,
             $self_x - 8fx * cos(a), $self_y - 8fx * sin(a),
             2fx, a, BOSS1AT2_BULLET(v), none);
}

async sub boss_at2_emitter() {
    var rank: int = global(GVAR_RANK);
    var count: int = 1;                // etCount(0, 1/1/3/5, 1)
    if rank == RANK_HARD { count = 3; }
    else if rank == RANK_LUNATIC { count = 5; }
    var boost: fx = 3.0fx;             // second VELTIME target: !E/N/H 3.0f, !LO 5.0f
    if rank == RANK_LUNATIC { boost = 5.0fx; }
    var gap: int = 100;                // wave interval: !E/N 100, !LO 30
    if rank >= RANK_HARD { gap = 30; }
    wait(300);                         // Boss1_at2: wait(300) before the loop
    var t: int = 300;
    var wave: int = 0;
    while t < SRC_LIMIT && wave < 700 {
        var base: angle = aim_player();  // etAim(0, 0) aimed fan, alpha 0
        if rank == RANK_LUNATIC {
            // !L etAngle(0, %RANDRAD / 60, .2617994f): one +-3deg rotation per wave
            base = base + (((rand(65536) - 32768) / 60) as angle);
        }
        if count == 1 {
            boss1at2_fire(base, boost);
        } else if count == 3 {
            boss1at2_fire(base, boost);
            boss1at2_fire(base - 15deg, boost);
            boss1at2_fire(base + 15deg, boost);
        } else {
            boss1at2_fire(base, boost);
            boss1at2_fire(base - 15deg, boost);
            boss1at2_fire(base + 15deg, boost);
            boss1at2_fire(base - 30deg, boost);
            boss1at2_fire(base + 30deg, boost);
        }
        var d: int = gap;
        if t + d > SRC_LIMIT { d = SRC_LIMIT - t; }
        if d > 0 { wait(d); }
        t = t + d;
        wave = wave + 1;
    }
}
